import json, math, hashlib
from pathlib import Path
ROOT=Path(__file__).parent
OUT=ROOT/'output'; OUT.mkdir(exist_ok=True)
prior=json.loads((ROOT/'source/Character_Register.json').read_text())
story=json.loads((ROOT/'source/Story_Framework.json').read_text())
burrow=json.loads((ROOT/'source/Burrow_v2.1.json').read_text())
world={'title':'MADGER - The Open Ways World Atlas','edition':'3.0.0','date':'2026-10-20','scope':'Complete foundation atlas for the eight-region story setting: 40 named characters, 14 principal communities, 9 factions, 8 encounter sites and a reproducible building system. The wider planet can grow by additive editions. This is a fictional production atlas, not a claim that every unnamed person, future adventure or architectural engineering detail exists.','authority':'New owner-commissioned development. Preserves Burrow v2.1 geometry, approved hero designs and voices, and character/story revision 1.1. This edition resolves reserved exterior geography, companion origins and supporting biographies. New art is authored visual development; established hero references remain controlling.','coordinates':{'regional':'kilometres; +X east, +Y north; Burrow Sunwell at (0,0). Z metres above Sunwell datum; vertical exaggeration prohibited in plan measurements.','local':'metres; settlement origin is its named civic anchor; +X east, +Y north, +Z up. Local points rotate 0 degrees into the regional grid.','calendar':'360-day year, twelve 30-day months, six-day weeks. Pilot is year 0, late spring. Relative negative years count backward; no claim that these are Earth years.','travel':'Ordinary walking 24 km/day; loaded convoy 18 km/day; regional river passage 50 km/day; sea passage 90 km/day; sky passage 100 km/day in safe weather. Route days include explicit layovers where stated. No fast travel enters anime history.'},'regions':story['regions'],'communities':[],'characters':[],'factions':prior['factions'],'sites':[],'history':[],'stories':[]}

# Each settlement is a distinct place, with a lived economy and competing local interests.
rows=[
('BRW','The Burrow','REG-01',0,0,0,'basin',2400,'A welcoming limestone basin and a larger inhabited underground town.','Ward assemblies and shared services; Madger has no permanent veto.','Food gardens, workshops, care, teaching and caravan exchange. Imports salt, metals, medicine and some grain.','Bridge Day celebrates ordinary repairs with races, food and deliberately terrible songs. Surface and underground households exchange supper invitations.','Sunwell and Underhall by day; inner shelter boundary during a surface overrun.','No new exterior route, shaft or bypass is added to its sealed defenses.','Six years of collective construction grew from a camp and common store into five neighborhoods. Existing footprints and route graphs are inherited verbatim.','Welcome without dependence; the missing-road crisis tests whether fear will make the town surrender its values.','Existing Burrow plans control all 37 primary areas and seven detailed rooms.'),
('EXT-01','Reedbank','REG-01',5,-45,4,'river',3600,'Raised river houses, terracotta roofs, timber wharves and long flood stairs.','An elected harbor council; depot owners can petition but do not own the river.','Boat repair, reeds, ceramics and fish; grain arrives from the floodplain.','At Watermark Night families repaint their flood marks and launch harmless paper boats carrying promises they actually kept.','High-bank kitchen and public lofts during flood season.','Low wharves close in floodwater; boats follow marked channels.','Founded 240 years ago around a ferry; survived the Severance on local river trade. The flood seven years ago scattered households and strengthened depot power.','Dara and Hollis remain here. Veyra buys influence while kitchen volunteers investigate unfair allotments.','Reedbank Kitchen|Flood Charter House|Kest Depot'),
('EXT-02','Stonewake','REG-01',-36,55,320,'quarry',2160,'Occupied quarry terraces, stone arches, copper roof caps and bright workshop shutters.','Workshop delegates, quarry residents and water crews share a three-chamber council.','Cut stone, metal fittings and trained builders; imports grain and timber.','The Unfinished Fair exhibits useful failures alongside fine craft; apprentices explain what they learned.','Public lower yard and braced civic galleries.','Old quarry faces have marked collapse zones; deep descent is licensed and physically separate from the Burrow.','Founded 310 years ago; abandoned extraction faces were converted into homes. A work-platform failure nine years ago changed local training rules.','Eris wants productive change; Oren fears rushing. Gorilla must return as a colleague rather than the one who must save everyone.','Commonworks Hall|White Family Workshop|Deep Descent House'),
('EXT-03','Latchford','REG-01',28,-8,12,'crossroads',2880,'A bustling junction town of inns, arcades, wagon courts and public dispatch boards.','Rotating neighborhood council and an independent route tribunal.','Transport, repair, lodging and records; reliable information is an export.','The Six Roads Supper seats strangers by destination, not rank. Stories are traded before prices.','Accord courtyard and staffed arrival houses.','An unfamiliar seal is checked against a second source; private rented rooms are not automatic criminal sites.','Grew around three roads 180 years ago. The Severance made it a transfer hub; relay trade arrived 38 years ago.','Glass Thread rents limited rooms here. Honest dispatchers resent outsiders treating the whole town as a den of criminals.','Accord Convoy House|Six Roads Inn|North Relay Rooms'),
('EXT-04','Millmere','REG-01',54,-36,8,'canal',3600,'Working canals, painted mill wheels, brick workshops and narrow planted bridges.','Canal wards elect stewards; worker cooperatives operate many workshops.','Paper, instruments, small machines and food milling; imports ore and hardwood.','During Wheelstill Day every mill stops for inspection, music and races using hand-powered toy boats.','Canal schools and elevated public bridges.','Wheel pits and locked sluice works are industrial hazards, not secret monster entrances.','A mill settlement for 220 years. Unequal restoration after a flood pushed some young residents away; Nix learned to distrust official accounts.','Lume wants Bot to visit without feeling summoned. Nix tries to turn old neglect into permission to injure new strangers.','Varr Workshop|Canal Records House|Wheelstill Market'),
('EXT-05','Willowmere','REG-01',40,65,72,'orchard',1728,'Orchard lanes, rain gardens, low timber teaching halls and the first enormous canopy roots.','Growing circles and household delegates; water decisions are recorded publicly.','Fruit, seeds, dyes and local guides; imports tools and salt.','Seed Exchange pairs every rare seed with the story of who kept it alive. Children invent impossible plants in clay.','Teaching courtyards and the fixed ridge path.','Migration-season root corridors are closed at dusk until guides inspect them.','Founded 145 years ago by growers and guides at the forest margin. It stayed small by choice rather than isolation.','Neri and Sori disagree about returning; each has relatives and responsibilities in two places.','Seed House|Ridge Teaching Hall|Canopy Guide Lodge'),
('EXT-06','Cinder Cuts','REG-07',-140,-42,410,'freight',1152,'Old freight cuttings, exposed basalt terraces, repaired worker homes and abandoned sidings.','Three occupied terraces maintain a residents council; Riven Claw occupies only the disused eastern spur.','Salvage, hauling and ceramic repair; independent workers trade with Kettle Crown.','The Last Whistle fair honors retired engines with percussion and shared food.','Occupied west terraces and public worker hostel.','Eastern Spur is controlled by Riven Claw; steam trenches and unstable freight edges are marked.','Built 75 years ago as a freight district after the Severance. A route diversion 18 years ago reduced work; raiders arrived seven years ago.','Dreg has family in the legitimate neighborhood. Brakka tries to turn neglected workers into a captive supply base.','Workers Hostel|Salvage Exchange|Eastern Spur Stronghold'),
('EXT-07','Crownrest','REG-02',100,135,180,'canopy',1440,'A settlement on six colossal living crowns, joined by adjustable bridges above a fixed stone ridge.','Each crown chooses a delegate; bridge crews can suspend a crossing despite a festival timetable.','Resin craft, living fiber, medicine plants and route guidance; grains are stored in the fixed ridge depot.','The Returning Shade festival reunites crowns after migration; dancers adjust tempo to swaying branches.','Fixed Ridge House during storms; tethered crown decks in normal weather.','A drifting crown changes its local position by up to 180 m during wet season; the baseline plan records spring anchor positions.','Founded 160 years ago by orchard people and canopy guides. Its architecture moves with trees rather than forcing roots to stand still.','Senn knows a route that records call abandoned. Saving outsiders may expose a shelter his community promised to keep quiet.','Ridge House|Bridgewright Pavilion|Resin Exchange'),
('EXT-08','Ossara','REG-03',230,25,95,'rings',5760,'A sandstone city of shaded courts, wind towers, turquoise shutters and glass dunes beyond its walls.','Public well assemblies and craft wards; the Salt Crown company is a powerful rival, not the government.','Optical glass, salt, astronomy and caravan goods; roof cisterns and three seasonal aquifers support agriculture.','The Night of Two Shadows uses lanterns and mirrored sails for street theater; guests must bring a story, not a gift.','Public cistern courts and deep caravan inns.','Dune travel stops during glass storms; reflected light is not a reliable navigation bearing.','Founded 420 years ago at three wells. An old observatory survived the Severance, but its archives preserve only fragments.','Maela discovers some water debts are fabricated. Kavar sells stability while deliberately keeping a competing well closed.','Three Wells Court|Mirror Observatory|Salt Crown Counting House'),
('EXT-09','Nacre Quay','REG-04',170,-170,0,'tidal',4320,'A coral-colored port wrapped around stepped tidal basins and limestone arcades.','Harbor crews, salvage families and reef tenders elect a tide council.','Sailing, salt fish, reef gardening and salvage; fresh water comes from roof collection and inland springs.','Low Tide Theater stages plays on steps exposed for only an hour; everyone helps strike the stage before water returns.','Upper quay, rescue house and marked moorings.','The drowned archive opens only around low tide; reefback migration closes the outer channel seasonally.','Founded 280 years ago above an older drowned district. The sinking preceded the Severance; neither event caused the other.','Toma must choose between a profitable salvage claim and evidence belonging to living descendant communities.','Tide Council Hall|Rescue Sail House|Drowned Archive'),
('EXT-10','Aurel Quay','REG-05',235,140,1600,'sky',2304,'Three floating basalt islands joined by cargo spans, with counterweights, hanging gardens and ochre sails.','Independent dock cooperatives and neighborhood crews; no captain owns an island.','Weather routing, liftstone shaping and sail making; food arrives by cargo craft and terrace gardens.','Weight Day is a comedy festival where teams build the lightest absurd object that still performs its job.','Sheltered inner moorings and grounded storm refuges on each island.','Liftstone responds to local fields, with strict load budgets; it cannot be carried elsewhere to float arbitrary cities.','Established 130 years ago around seasonal anchor fields. Its first charter outlawed selling residents with a vessel.','Eri refuses a lucrative overloaded launch. Serik offers stranded crews a rescue that becomes a protection racket.','Counterweight Hall|Sailmakers Court|Windward Rescue Dock'),
('EXT-11','Hushvale','REG-06',-60,260,980,'cavern',2016,'A geothermal town under a glacier shoulder, with copper roof caps, steam gardens and blue ice light.','Winter guilds and household delegates share stores; the archive order holds expertise, not unlimited civil authority.','Insulation cloth, cold storage, optical ice study and mountain guiding.','The Quiet Hour marks storms survived; the following feast is deliberately noisy and full of imitation bird calls.','Warm civic cavern and staffed wayhouses.','Echo ice can repeat old sounds; choirwraith habitat is mapped beyond the warm ridge.','Founded 360 years ago around springs. Routekeepers here cut resonance links during the Severance and inherited both gratitude and blame.','Ysolde finds a true warning mixed with a forged prohibition. Ossa cannot accept that stewardship requires other people to judge the evidence.','Winter Hall|Echo Archive|Warm Ridge Observatory'),
('EXT-12','Kettle Crown','REG-07',-180,-40,620,'volcanic',3456,'A city on volcanic shelves, with obsidian stairs, red ceramic roofs and lush hot-spring gardens.','Forge cooperatives, growers and freight neighborhoods negotiate heat and water shares.','Ceramics, tempered metal and heat-grown fruit; imports timber and cool-water crops.','The Cooling Feast celebrates a finished kiln cycle; rival makers exchange deliberately ridiculous cups.','Stone civic courts and supervised hot-spring gardens.','Gas troughs and active channels close under marked conditions; lava is not casually crossed by being brave.','Founded 190 years ago on old cooled shelves. Industrial growth enriched the city while the diverted freight line harmed Cinder Cuts.','Kesh must acknowledge the town profited from a decision that hurt its neighbors without accepting Brakka as their representative.','Common Kiln Hall|Spring Garden House|Freight Mediation Hall'),
('EXT-13','Lumen Tide','REG-08',-42,63,-1600,'deepsea',4608,'A vertical limestone city above a subterranean ocean, with mineral windows and fungal shore gardens.','Harbor, air and food circles elect rotating speakers; surface visitors follow local law.','Fungal textiles, mineral instruments and cavern navigation; imports grains through Stonewake trade.','The Lantern Descent lowers lamps to remember people who left on voyages; it ends with dancing, not a funeral.','Ventilated upper civic terraces and inspected refuge docks.','Pressure, air quality and sea level determine access; no passage connects it directly to the Burrow.','A continuous community for at least 600 years, with several written founding traditions. Its oldest harbor predates the Open Ways.','Namu wants surface partnership on equal terms. A rediscovered chart threatens to invite extractive expeditions into sacred nesting waters.','Tide Speakers Hall|Fungal Exchange|Pressure Gate House')
]
for row in rows:
 keys=['id','name','region','x','y','z','layout','population','appearance','government','economy','custom','safe','danger','history','conflict','buildings']
 d=dict(zip(keys,row));d['position_km']=[d.pop('x'),d.pop('y')];d['datum_z_m']=d.pop('z');world['communities'].append(d)

# Full card development: unique history, desire, contradiction, relationships, arc, repeatable stories and visual anchors.
cards={}
def card(id,age,height,look,past,want,flaw,ties,arc,storyhook,secret,voice='No voice assigned; do not substitute an existing hero voice.'):
 cards[id]={'age':age,'height_m':height,'design':look,'history':past,'desire':want,'contradiction':flaw,'relationships':ties,'arc':arc,'story_engine':storyhook,'writer_truth':secret,'voice':voice}
card('GORILLA_WHITE',28,2.15,'Approved white/sandy fur, tan face and chest, blue eyes, broad long arms and exact established proportions. Work tools are removable props, not new armor.','Born in Stonewake to a family of stone fitters. At nineteen, he noticed a temporary platform straining but tried to hold it while others cleared it instead of demanding a full stop. The platform failed; his older sister Eris survived with an injured hand and recovered, while an apprentice lost months of work. He testified honestly and helped repair the damage. Three years later, at twenty-two, he joined the Burrow builders and met eighteen-year-old Madger during their first-year storm bracing job. Madger accepted his refusal of a shortcut and stayed for the slower work.','To build places where nobody is left exposed, and to make a beautiful resonant instrument rather than another emergency brace.','He treats enduring pain as a private duty. His patience can become stubborn control: he moves someone out of danger without listening to what they know.','Madger is his closest building partner. Eris loves him but refuses to be the story of his failure. Oren taught him; Iona checks his assumptions. Edda insists care is reciprocal. Tavi wants his praise and fears disappointing him.','Pilot: accepts help with an ordinary lift. Season one: delegates evacuation work and lets Edda treat an injury. Season two: returns to Stonewake, learns that Eris remembers his silence more than his weakness, and teaches Tavi how to stop a job. Season three: lets a smaller teammate lead a rescue he cannot physically reach.','A craft competition where strength is useless; a bridge rescue with a load he must release; a visit home where his family is happy without needing him to fix anything.','The platform failure was a chain of bad decisions, not sabotage. Eris never blamed him for being insufficiently strong. His hardest apology concerns making her recovery about his guilt.','Approved Chad / Baritone R7 only; Mtmp3KhFIjYpWYRycDe3 and approved processing. Friendly youthful baritone, measured pace; no new render.');
card('MADGER_BOT',8,1.25,'Approved silver/black metal body, mechanical face, amber optics, blue lit joints. No organic muzzle. Panel seams and proportions inherit the official reference.','Activated eight years before the pilot at Lume Varr’s Millmere workshop as a general maintenance learner. Lume and a cooperative built the body; sustained learning formed an independent person, not a remote employee. At age three Bot chose the Burrow, five years before the pilot, after working on a convoy repair. Madger welcomed a colleague who asked questions and could decline work.','To be trusted even when an answer is incomplete, and to compose a tune that is not optimized for anything.','Bot confuses usefulness with certainty. He can preserve a fact while overlooking why sharing it would hurt someone. His memory has gaps from ordinary early storage replacement.','Lume is a parentlike maker, not an owner. Iona tests records against machinery. Pell helps distinguish public evidence from private care records. Patch recognizes old Varr fittings and envies Bot’s freedom.','Pilot: preserves D17 without guessing. Season one: admits a source was compromised and asks neighbors to verify physical conditions. Season two: declines a maker’s well-meant diagnostic request until its scope is agreed. Season three: chooses to discard a stolen private dataset while preserving the evidence needed to prove a crime.','A comedy about learning music; a mystery in which a perfect timestamp describes the wrong event; a reunion with a maker who must learn to ask permission.','No hidden master switch or secret evil personality. Lume replaced a failing memory module with Bot’s consent during early development; the lost material is not a magical universal key.','Approved Brodie / Friendly Smooth R4 only; rHWSYoq8UlV0YIBKMryp and approved processing. Friendly youthful robotic delivery.');
card('SNOW_WHITE',6,0.61,'Approved adult shepherd anatomy, long muzzle, slender legs, short coat, cream-frosted tail, rose collar and matching prominent SW charm. Height measured at shoulder. Four-legged movement.','Born with a Wayfarer household near Latchford. Asha Bell raised her with patient scent games and ordinary household life. At three, when Asha retired from long routes, Snow spent increasingly long stays with Madger before settling with him. Asha visits; nobody abandoned her. Her familiar cue set comes from both homes.','Canine motivations: proximity to trusted companions, interesting scent work, play, food and a comfortable resting place.','A fresh moving scent can outrun her attention to a handler. Crowds, hot surfaces, fatigue and strong competing smells affect performance.','Madger is her primary companion. Asha remains familiar family. Gorilla makes a quiet resting place near work. Bot learns to wait for her body language instead of treating every bark as an alert.','Pilot: pauses and looks back at a physical trace. Season one: returns to lead companions to a stranded traveler rather than pursuing alone. Later: accepts a new search partner through repeated practice and rest. Progress is shown in behavior, never a spoken moral.','A largely wordless search episode; an old-handler visit; a playful market mix-up in which the interesting scent is completely innocent.','The pilot scent is ordinary canopy resin on a legitimate traveler’s gear. Snow cannot smell guilt, hacked signals or future danger. She receives rest and recovery after exertion.','Natural approved canine sounds only. No human dialogue, narration in her voice, telepathy or cloning.');
card('RES-01',34,1.18,'Warm brown rabbit, one darker ear tip, oat apron over a rust wrap tunic; round flour tin.','Grew up above Dara’s kitchen in Reedbank and learned bulk cooking there. Arrived in the Burrow four years ago for a workshop opportunity, not as a fugitive.','To open a communal recipe wall and finish a sketchbook of everyone’s hands.','Says yes because being needed feels like being loved, then becomes sharp when exhausted.','Jun is a close friend who notices fatigue; Dara is a mentor; Edda trades early shifts.','Moves from secret overtime to an honest limited menu, then teaches neighbors recipes without fearing replacement.','A banquet goes wrong when she hides a broken oven; a lost sketchbook reveals affectionate portraits people mistake for mockery.','Her most praised root bun was Jun’s improvement, which she initially forgot to credit.');
card('RES-02',17,1.24,'River otter, dark wet-brown fur, teal rolled sleeves, orange repair sash, short tool roll.','Born in Millmere and moved with family to West Deep two years ago. Apprenticed after repairing a toy wheel, then discovered real machinery was less forgiving.','To earn a traveling Commonworks placement without being seen as someone’s child.','Hides small errors to protect the appearance of competence.','Gorilla mentors craft; Iona teaches checks; Lume offers a future exchange.','Admits a misfit part before it fails, accepts the lost time, then becomes the person another apprentice can tell the truth to.','A repaired chair becomes a running comic prop; a contest tempts him to copy an elegant but unsuitable design.','He has kept the first rejected part as a reminder; it is not evidence of sabotage.');
card('RES-03',46,1.02,'Compact charcoal mole, muted blue work coat, copper-rim magnifiers and chalk ledger.','Trained in Stonewake ventilation crews, moved to the Burrow in its third year to help maintain expanding occupied levels.','To leave a system understandable enough that her absence is ordinary.','Accurate objections become contemptuous when others do not know her vocabulary.','Oren trusts her; Sori disputes allocations; Bot is a colleague, not her instrument.','Explains a risk in language a child can repeat, then accepts a grower’s observation that her measurements missed.','A water discrepancy with no villain; a teaching shift where her students invent a better inspection route.','She once missed a worn seal and recorded the mistake openly; her reputation was built after that, not on infallibility.');
card('RES-04',31,1.22,'Red panda with cream cheek patches, moss jacket, plum scarf, folding paper models.','Left Willowmere after teaching mixed-age growing classes and came to East Orchard three years ago.','To make curiosity a public habit rather than a school-only activity.','Plans every discovery so carefully that learners cannot surprise her.','Sori shares her home region; Jun challenges inaccessible signs; Senn sends seed stories.','Lets an unfinished question remain open, follows a student’s route, and changes the next lesson because of what happened.','Children design a misleading map; a visiting elder tells a history that contradicts her lesson plan.','She failed an entrance exam for a prestigious teaching hall and still hides the rejection letter.');
card('RES-05',39,0.94,'Hedgehog with warm gray spines, cream waistcoat, blue satchel, large round desk stamp.','Worked in Latchford arrival houses before moving to East Deep five years ago. He knows how frightening a small confusing form can be.','To make entering an unfamiliar place feel understandable.','Uses procedure to postpone the discomfort of making a judgment.','Madger needs his practical questions; Bot helps with records; Pip knows his former workplace.','Corrects a misleading rule publicly and takes responsibility for the people it delayed.','An unsigned invitation is genuine; a perfect-looking document is irrelevant to the visitor’s actual need.','He once sent a family to the wrong queue and never learned their names; the memory drives his care.');
card('RES-06',29,0.58,'Field mouse, tan fur, indigo vest, ochre paint-stained cuffs and a square brush case.','A Millmere sign painter who wanted more room for personal work; arrived four years ago and shares West Lantern routines with Mara.','To paint a mural that belongs to its neighbors rather than his reputation.','Keeps improving a useful object until nobody gets to use it.','Mara feeds him during long jobs; Neri tests his signs; Tavi trades repairs.','Releases a good-enough first version, watches people use it and improves it from observation.','A mural vote exposes an old disagreement; an urgent banner must work without words.','His neatest signature covers an old spelling error he has never confessed.');
card('RES-07',43,1.26,'Beaver, deep chestnut fur, sage tunic, cream shoulder cloth, practical handwash kit.','Worked in Reedbank recovery houses after the flood and joined East Deep four years ago.','To make care ordinary enough that strong people ask for it early.','Rest feels selfish when she can hear someone needing help.','Gorilla resists her advice; Mara understands her fatigue; Dara shares old flood memories.','Builds a rotating care team and takes a real day off, then returns without apologizing for it.','The town plans a surprise rest day that creates more work; a patient wants company instead of another solution.','She was not on the rescue boat Madger remembers; she met survivors afterward and corrects the story when asked.');
card('RES-08',36,1.3,'Copper fox with pale throat, olive overalls, violet seed pouch, pruning shears.','Grew up in Willowmere cooperatives and moved to Hearth Terraces for new growing terraces five years ago.','To keep enough diversity in the gardens that one bad season cannot ruin everyone.','Defends favorite experiments past the point where evidence supports them.','Iona argues about resources; Neri brings learners; Kesh offers heat-grown varieties.','Sacrifices a prized crop trial to protect shared supply, then runs a smaller honest trial next season.','A rare fruit tastes awful; an unexpected volunteer plant survives what carefully planted rows cannot.','One successful variety came from an accidental seed mix, not his deliberate breeding plan.');
card('ALLY-01',48,1.62,'Female ibex, swept horns, weathered blue convoy coat, red cord around a brass whistle.','Latchford convoy worker from sixteen, captain by thirty. At forty-one she chartered Reedbank’s second evacuation using Veyra’s concealed funding and accepted secrecy to get eighteen households out safely.','To make a promise of passage mean something real.','Will hide a morally complicated detail if she thinks disclosure will break confidence in the route.','Madger trusts her; Veyra knows her omission; Lark admires her; Asha is an old colleague.','The funding reveal costs her standing. She releases records, accepts another captain’s oversight and earns trust through subsequent choices.','A timetable versus a stranded stranger; a return to a place she once chose to leave behind.','Her shame kept the funding secret after immediate danger passed. The rescue was real and the silence was a choice.');
card('ALLY-02',68,1.04,'Older tortoise, olive shell with old repaired rim, burgundy work vest, long wooden straightedge.','Stonewake mason who helped shift workshops from guarded family secrets to teachable public craft. Trained Gorilla and Iona at different times.','To see pupils become teachers who disagree with him well.','Calls delay prudence even when it protects his own reputation.','Eris disputes his old methods; Gorilla still seeks approval; Kesh wants faster collaboration.','Authorizes a carefully bounded temporary repair, signs his responsibility and lets the younger builder explain it publicly.','An old prize-winning design fails modern needs; a student credits someone Oren once ignored.','His early fame relied on an uncredited team. He is willing to correct the record, but fears the ceremony.');
card('ALLY-03',26,1.12,'Magpie, black-and-white feathers, cobalt courier cape, red ankle cord and layered map wallet.','Millmere ferry runner who joined the Wayfarers at nineteen. Learned that a story travels faster than a correction.','To be the courier whose report people can build a journey around.','A source who makes her feel uniquely trusted can bypass her skepticism.','Sela is captain; Pip supplies tips; Tessera studies her habits; Senn is a respected route contact.','Publishes a correction with the same energy as the original claim and protects a source without laundering a lie.','A delivery race with conflicting obligations; a message whose intended recipient no longer wants it.','She once repeated a rumor about Nix’s family and never knew its full harm.');
card('KIN-01',52,1.16,'Female badger, salt-gray temple fur, warm cream muzzle, berry shawl and river-green apron; distinct from Madger.','Raised near Reedbank’s ferries; organized shared meals long before her son imagined a town. Stayed to rebuild after the flood.','To keep a kitchen where asking for food is ordinary, and finally learn a dance she has watched for years.','Offers help so quickly that she can miss when someone wants privacy.','Hollis is her partner; Mara her former helper; Madger her adult son, not her project.','Learns to ask before intervening in Madger’s dispute while holding him responsible for hurtful words.','A family visit without an emergency; two rival cooks discover they learned from the same neighbor.','She suspected the rescue had a wealthy backer but did not know Veyra paid.');
card('KIN-02',55,1.27,'Male badger, grizzled cheeks, navy work vest, patched tan trousers, folding boat rule.','A Reedbank boat fitter who built a cooperative after an employer withheld repair pay. Remained after the flood to keep local boats working.','To finish a small pleasure boat with no commercial deadline.','Uses practical criticism when the more difficult truth is that he misses his son.','Dara understands his evasions; Madger hears disapproval; Gorilla enjoys quiet work beside him.','Tells Madger what he is proud of without appending a warning, then asks for company instead of inventing a repair.','A fishing trip turns into a stubborn contest; a supposedly useless offcut solves a household problem.','His first boat was badly balanced. He keeps its crooked miniature on a high shelf.');
card('VIL-01',45,1.36,'Female sable, deep chocolate fur, ivory chin, ink-blue tailored long coat, one warm brass clasp, composed posture.','Reedbank depot worker who rose through crisis logistics. At thirty-eight she diverted reserves to fund a rescue convoy; later consolidation convinced her that only centralized control prevents chaos.','To make the Burrow sign a permanent exclusive supply agreement and prove that her form of order is indispensable.','Her generosity becomes a claim of ownership. She remembers every life she helped but discounts lives injured by her conditions.','Corvin negotiates; Bale controls stock; Sela knows the rescue truth; Kavar is an occasional commercial counterpart.','Season one: her offer fails despite a genuine good deed. Later: she must choose between saving her ledger and releasing stock without a binding promise. An act of repair can cost her power without erasing accountability.','A negotiation where her diagnosis is partly right; a crisis in her own depot that exposes how little her workers trust her.','She did not cause the flood, invent Nix’s grievance or command Brakka’s raid. Her culpability is her present coercion.');
card('VIL-02',38,1.13,'Male stoat, winter-cream throat, charcoal fitted coat, lilac cuffs, narrow document case.','Latchford inn clerk who discovered that introducing two powerful people paid better than serving them. Became Veyra’s broker eleven years ago.','To be required at every important table, with enough private leverage never to be dismissed.','Mistakes being tolerated for being trusted.','Buys jobs from Nix, bargains with Pip and flatters Veyra while hiding small side fees.','Loses control when two clients compare accounts. Can confess a real crime to protect a subordinate or sacrifice them and become more isolated.','A perfect contract depends on one deliberately misunderstood word; a public feast seats him beside someone he exploited.','He has no secret authority over Glass Thread; Tessera keeps evidence of his extra payments.');
card('VIL-03',49,1.43,'Male badger, broad gray muzzle, maroon warehouse coat, square brass inventory tags; no resemblance to Madger beyond species.','Stonewake stores worker who survived winter shortages and joined a depot chain seeking regular provision.','To prevent chaotic scarcity by controlling who receives what.','Turns a person waiting for medicine into a tolerable inventory discrepancy.','Veyra values his reliability; Dreg secretly sells him selected freight through a fence; Edda forces him to face recipients.','Falsely calls a deliberate withheld shipment a delay. Later chooses to release it and testify, sacrificing status rather than receiving instant absolution.','A depot count with a hidden human cost; an old neighbor recognizes him behind a shuttered counter.','He knows a specific allotment policy causes harm; ignorance is not his defense.');
card('VIL-04',24,1.21,'Nonbinary pine marten, dark brown fur, cream throat bib, asymmetrical teal scarf, weathered plum coat, copper clamp toolkit.','Born in Millmere, spent teenage work seasons in Reedbank repair yards with Madger. After the flood they returned to unequal restoration and grew bitter. Their correspondence faded. Later formed Glass Thread around paid access jobs and a campaign to expose erased communities.','To force powerful people to acknowledge the communities omitted from official routes, and to be recognized as the one who forced the truth into daylight.','A true grievance becomes permission to make strangers into instruments. They crave Madger’s respect while trying to prove his welcome is naive.','Tessera wants anonymity; Patch wants out; Corvin pays; Madger remembers an inventive friend, not a monster.','Season one: accepts a consequence long enough to prevent one death, then flees. Later must return stolen evidence, testify and accept restrictions before friendship can become possible.','An old childhood joke during a hostile meeting; a rescue where telling the truth destroys their bargaining advantage.','They did not intend the root bridge crossing but knowingly created unreliable guidance. Intention does not cancel foreseeable harm.');
card('VIL-05',32,1.05,'Female jackdaw, charcoal feathers, pale gray eyes, dull olive traveling coat with reversible ochre lining, plain ring.','Latchford dispatch assistant who learned whose manners made staff stop checking. Built a career in impersonation and access brokerage.','To remain impossible to pin to one identity while owning everyone else’s secrets.','Needs enough recognition from expert peers to risk showing her signature.','Nix provides public noise; Patch keeps equipment running; Corvin is useful and contemptible.','Her planted D17 test becomes traceable through ordinary human evidence. She sacrifices a profitable identity to escape, leaving a narrower network.','Two people claim the same appointment; a witness remembers an act of kindness she thought nobody saw.','D17 is her limited receipt replay via a compromised trade relay, not remote control over the Burrow’s physical gates.');
card('VIL-06',27,0.92,'Male gecko, sage skin with ochre speckles, rust utility vest, amber magnifier and repaired bag.','Reedbank electronics apprentice who followed better pay into gray-market maintenance. Nix first hired him to repair a legal relay.','To leave with enough money to run a legitimate workshop.','Insists equipment has no morality while selecting jobs that enable harm.','Bot shows a life he thinks he missed; Tessera keeps incriminating receipts; Nix alternates warmth and pressure.','Stops maintaining a dangerous relay, preserves evidence and accepts the consequences of his prior work.','A broken device is also the only evidence against him; a child admires him for the wrong accomplishment.','He has helped harmful operations knowingly. Defection requires repair and truthful testimony, not a new nickname.');
card('VIL-07',41,1.48,'Female wolverine, dark umber coat, pale forehead streak, battered red shoulder wrap and functional hooked staff.','Born in Cinder Cuts before freight decline. Began as a convoy guard, learned that fear brought faster payment, and built a raiding crew seven years ago.','To make every neighboring route pay tribute and never again be dismissed as expendable labor.','Calls fear respect and wastes the food she claims to protect on displays of dominance.','Dreg supplies; Vessa scouts; Serik is an unreliable distant buyer; workers in her home district mostly want her gone.','Loses a raid because her crew protects supplies rather than her spectacle. Later doubles down or faces a humiliating survival that requires accepting mercy.','A feast funded by theft; a subordinate discovers that her invulnerable legend began as a frightened accident.','No one secretly appointed her guardian of the Cinder Cuts. Her hardship explains her anger, not her entitlement.');
card('VIL-08',44,1.52,'Male boar, bristled charcoal head, short natural tusks, ochre freight vest, heavy blue belt pouches.','Millmere hauler who followed freight work west and then joined Brakka for reliable shares.','To feed his crew and support relatives in the legitimate Cinder Cuts neighborhood.','Treats organized theft as honest work because it has schedules.','Brakka frustrates him; Bale buys indirectly; Vessa knows his family route.','Refuses to burn captured supplies for intimidation, triggering a split. Restitution to victims is the test of change.','A stolen crate contains something useless to raiders but vital to a village; his family refuses money they know came from theft.','He has quietly kept records of victims, initially as a bargaining asset rather than conscience.');
card('VIL-09',30,1.42,'Female eagle, tawny feathers, cream head markings, slate flight harness and coral map ribbon; wings stay anatomically consistent.','Cinder Cuts ridge guide who sold observations to whoever paid and joined Brakka for protection.','To own her route knowledge and never be treated as expendable.','Confuses refusing loyalty with refusing responsibility.','Brakka commands her; Pip buys sightings; Eri offers legitimate guiding work but requires disclosure.','Warns one convoy because a promised raid crosses her line, then must reveal previous sold routes to earn employment.','A dangerous wind makes her walk among people who fear her; two employers purchase the same promise.','Flight has weather, payload and fatigue limits; she cannot enter sealed rooms or carry a whole rescue party.');
card('IND-01',35,1.12,'Raccoon, soft gray fur, black eye mask, russet layered waistcoat, turquoise bead and many small labeled pockets.','Latchford market child who learned to mediate trades and gradually crossed into fencing stolen freight.','To be welcome in every market without answering for where goods came from.','Neutrality is a story they tell when choosing the profitable side.','Lark buys information; Corvin pays commissions; Vessa brings sightings; Pell remembers their honest first stall.','Returns a valuable stolen item and names its source, losing criminal customers before rebuilding lawful trade.','An object has two convincing owners; a bargain turns out to be a family memory somebody should never have sold.','They know some goods are stolen. Cheerfulness is not innocence.');

new=[
('NEW-01','Senn Rill','Adult male red squirrel','Crownrest','FAC-07',29,1.02,'Rust-red squirrel, long tail, cream neck, leaf-green split coat, amber resin clasp.','A crown bridgewright raised between a moving village and the fixed ridge school. His mother helped conceal a refuge route when toll collectors threatened it.','To keep Crownrest open to friends without selling its private paths.','Treats every outsider’s question as a possible theft.','Neri knows his aunt; Nix used a true story from his community; Lark values his corrections.','Shares a limited route with accountable partners and stops confusing secrecy with protection.','A root bridge must be cut to save the crown; a festival guest knows a song no outsider should know.','The concealed shelter contains ordinary families, not a weapon or chosen heir.'),
('NEW-02','Maela Siroc','Adult female sand cat','Ossara','FAC-07',33,1.12,'Sand cat, pale gold fur, broad ears, turquoise head wrap and ivory layered traveling coat.','A public well examiner from a family of caravan cooks; learned optics to distinguish real water readings from reflected traces.','To reopen a public well and prove its water belongs to the city.','Her correct conclusions can become contempt for people afraid of change.','Kavar owns the disputed equipment; Toma carries archive evidence; Bot helps compare records but needs her local knowledge.','Wins a well through shared evidence, then lets neighbors set use rules she would not have chosen.','A mirage appears to prove a witness lied; a rescue costs her the instrument that could win her case.','The well is viable but cannot supply unlimited growth; victory still requires restraint.'),
('NEW-03','Toma Brine','Adult male sea otter','Nacre Quay','FAC-07',42,1.36,'Sea otter, silver whiskers, indigo sea coat, coral sash, polished shell compass.','Raised by reef gardeners, became a salvage captain and bought a ship with a crew cooperative.','To find a lost harbor chart and retire with a vessel that belongs to its crew.','Calls salvage fair discovery even when living families have prior claims.','Maela needs his archive passage; Sela respects his weather judgment; Namu disputes a mineral charter.','Returns a claim voluntarily and accepts a smaller share in an expedition governed by descendants.','A submerged feast hall opens for one tide; a rival rescue crew arrives first and deserves the credit.','His best chart was copied from a community archive without proper permission.'),
('NEW-04','Eri Aster','Adult female fruit bat','Aurel Quay','FAC-07',28,1.18,'Warm brown fruit bat, plum wing membranes, cream flight tunic, ochre sash and brass weight tokens.','A sailmaker’s daughter who survived a captain’s overloaded departure as a young crew member and became a dock rigger.','To captain a cargo craft without compromising her load rules.','Overprepares until a safe opportunity passes.','Serik offers shortcuts; Vessa could become a guide; Gorilla respects her refusal of a heroic overload.','Makes a bounded launch with incomplete weather knowledge and turns back when conditions change, even before an audience.','A comic cargo manifest hides a living garden; two islands require rescue but one craft cannot take everyone at once.','She once signed a load count under pressure; the survivor story is also a confession.'),
('NEW-05','Ysolde Rime','Adult female arctic hare','Hushvale','FAC-09',37,1.3,'Arctic hare, ivory fur, long dark-tipped ears, glacier-blue coat, copper scarf pin.','An archive interpreter trained to separate echo-ice sound from later stories attached to it.','To publish the actual Severance record, including her order’s necessary and self-serving choices.','Facts become armor against grief; she neglects how a revelation lands on people.','Ossa taught her; Oren wants technical evidence; Bot recognizes her discomfort with uncertainty.','Challenges the forged prohibition while preserving a real dangerous closure. Truth becomes a shared burden rather than a triumphant exposure.','An old voice repeats a sentence in the wrong order; an apparently heroic ancestor made a consequential mistake.','Her own family benefited from prolonged closure, and she publishes that fact too.'),
('NEW-06','Kesh Vatra','Adult male salamander','Kettle Crown','FAC-02',40,1.28,'Copper-orange salamander, dark mottled skin, cobalt smith apron, red ceramic wrist guards.','A hot-spring grower’s son who became a ceramic engineer and council mediator.','To connect prosperous Kettle Crown to neglected freight neighborhoods through useful work.','Believes a clever device can replace a difficult apology.','Oren is a collaborator; Sori wants seeds; Brakka invokes his town’s neglect; Dreg’s relatives petition him.','Secures a fair freight agreement after acknowledging past decisions and letting affected workers write terms.','A forge competition rewards beauty over strength; a miraculous new pipe works brilliantly and has no affordable repair.','The freight diversion helped his first workshop succeed; he is implicated without being its sole author.'),
('NEW-07','Namu Deep','Adult nonbinary axolotl','Lumen Tide','FAC-07',51,1.22,'Pearl-gray axolotl, rose external gills, dark teal woven coat, amber mineral beads; humid habitat needs matter.','A harbor navigator from a long-established deep-water community, chosen as a rotating speaker for surface relations.','To trade knowledge without turning the Hollow Sea into a resource claim.','Withholds so much context that partners cannot tell a boundary from a threat.','Toma seeks passage; Eris manages surface descent; Ossa’s order holds an old partial chart.','Explains a protected route without surrendering restricted nesting grounds, and accepts a visitor’s useful correction.','A surface map omits an inhabited shoreline; a lost ship returns carrying the wrong season’s cargo.','Their city’s founding traditions disagree; no single recovered tablet settles whose family belongs.'),
('NEW-08','Kavar Dune','Adult male fennec fox','Ossara','FAC-04',47,1.16,'Fennec, pale fur, huge ears, cream robe with narrow gold edging and dark teal gloves.','An Ossara pump trader who acquired wells during successive dry seasons.','To make every caravan purchase his water certificates.','Frames dependence as efficient planning and cannot tolerate a public supply that he does not control.','Veyra trades with him; Maela challenges him; Corvin offers outside contracts.','His fabricated debt is exposed, but removing him does not refill the aquifer. He may surrender equipment or destroy his standing further.','A generous water donation hides a binding claim; a desert storm strands him with people denied his service.','He ordered a viable competing pump kept closed and falsified the maintenance account.'),
('NEW-09','Serik Vane','Adult male bat','Aurel Quay','FAC-08',39,1.32,'Slate-gray bat, burgundy wing membranes, long black flight coat, amber scarf and hook-ended cargo pole.','Former rescue captain expelled after turning a weather emergency into a ransom negotiation.','To control the passages between the floating islands and sell protection from his own crews.','Needs to be admired as a rescuer while arranging circumstances that require rescue.','Eri refuses him; Vessa sells occasional observations; Brakka is a distant transactional contact, never a subordinate.','Loses the flattering story when freed captives testify. His tactical skill remains real and makes pursuit difficult.','A rescue beacon is genuine but its owner dangerous; his lieutenant must choose between saved passengers and the captain’s share.','He cannot create storms, control liftstone fields or command every sky pirate.'),
('NEW-10','Ossa Quill','Older female snowy owl','Hushvale','FAC-09',73,1.54,'Snowy owl, pale barred feathers, midnight-blue mantle, copper archival seals and one frost-darkened wing tip.','An archivist raised by a parent born just after the Severance. Inherited the stories of genuine protective closures and later extended authority through altered records.','To prevent another route catastrophe by keeping the right to decide who may reconnect anything.','A necessary historical sacrifice becomes justification for permanent control.','Ysolde is her student; Namu has independent records; Veyra sometimes benefits from closed routes but did not create the order.','Evidence forces her to distinguish a real dangerous coupling from a fabricated prohibition. She must surrender exclusive judgment or become the danger she fears.','A villain tells the truth about a hazard; the heroes need a technical procedure from someone they must also hold accountable.','She forged one modern closure order; she did not cause the original Severance 92 years ago.'),
('NEW-11','Lume Varr','Older female hare','Millmere','FAC-02',55,1.34,'Gray hare, cream ear interiors, violet rolled-sleeve coat, amber work goggles and blue ceramic mug.','Cooperative instrument maker who helped build Bot’s body eight years ago. Supported his departure for the Burrow five years ago but still slips into parental instruction.','To see her creations become people who can tell her no, even when that hurts.','Calls a request routine maintenance when it is really worry about being left behind.','Bot is family, not property; Tavi wants an apprenticeship; Patch recognizes her fittings.','Asks permission, accepts refusal and shares her own uncertainty. Their reunion becomes an adult relationship.','A repair visit becomes an awkward holiday; an old prototype is useful without being another conscious Bot.','No ownership clause or remote shutdown right survives Bot’s independent consent.'),
('NEW-12','Asha Bell','Older female collie','Latchford','FAC-03',62,1.4,'Sable-and-white anthropomorphic collie, soft green coat, orange knitted scarf and walking staff; distinct from quadrupedal Snow.','A Wayfarer handler and route cook who raised Snow within a household and retired three years before the pilot.','To keep meaningful friendships after leaving the road and teach a new handler without recreating herself.','Pretends not to miss the work, then gives unsolicited route advice.','Snow recognizes her; Madger respects her cues; Sela is an old colleague.','Accepts being needed differently, with visits and teaching rather than emergency journeys she cannot sustain.','Snow’s reunion is joyous without implying she must choose one family; an old route recipe reconnects two travelers.','Retirement was a deliberate good decision, not a secret illness or abandonment.'),
('NEW-13','Eris White','Adult female gorilla','Stonewake','FAC-02',34,2.02,'White/sandy gorilla, tan face, blue-gray eyes, slate work wrap and copper measuring chain; no armor.','Gorilla’s older sister and a skilled terrace builder. Injured at twenty-five in the platform failure, recovered and adapted her work. Stayed in Stonewake and became a respected crew lead.','To be recognized for what she built afterward rather than the accident.','Turns independence into a refusal to admit when a task is difficult.','Loves Gorilla but rejects his guilt rituals; argues with Oren; guides Namu’s visiting crews through surface works.','Asks her brother for specific help without letting him take charge of her life. Both learn mutuality.','A sibling building contest; a letter congratulates her brother for work she actually led.','She never needed him to be invulnerable. She wanted him to listen when she said the platform should be emptied.')]
for d in new:
 id,name,identity,origin,fac,age,h,*fields=d
 prior['characters'].append({'id':id,'name':name,'group':'Regional cast','identity':identity,'origin':origin,'affiliation':fac,'seed':fields[2]})
 card(id,age,h,*fields)
madger=json.loads((ROOT/'source/MADGER_001.json').read_text())
for c in prior['characters']:
 d=dict(c);d['origin']=d['origin'].replace(' [seed]','');d['status']='Developed baseline 3.0'
 if c['id']=='MADGER':
  d.update({'age':24,'height_m':1.12,'design':burrow['heroes'][0]['design'],'history':'Reedbank-born founder; childhood friend Nix; flood promise at seventeen; collective founding at eighteen. Parents Dara and Hollis alive. Full card revision 1.1 remains part of this atlas.','desire':'A welcoming home and a life large enough to satisfy his curiosity.','contradiction':'Confuses daring rescue and being needed with reliable leadership.','relationships':'Gorilla, Bot and Snow are partners with distinct agency; Sela concealed Veyra’s rescue funding; Nix knows him before he became a founder.','arc':'Share responsibility; choose rescue over pursuit; accept a complicated founding story; venture outward without treating the Burrow as a possession.','story_engine':'Exploration, family visits, mysteries, comic overcommitment and consequential defense.','writer_truth':'Veyra helped fund the second flood convoy. The flood was natural and all eighteen households survived.','voice':'Approved Excited Teen R2 / OvSI8qvaDkaFiIdSCWRw only.','full_card':madger})
 else:d.update(cards[c['id']])
 d['skills_and_limits']='Species anatomy, training, tools, fatigue and local knowledge constrain action. No unlisted magic or universal hacking.'
 d['art_status']='Inherited approved hero reference' if c['group']=='Core hero' else 'New design developed for this edition; exact colors and silhouette set by card and cast plate.'
 world['characters'].append(d)
world['factions'] += [
 {'id':'FAC-07','name':'Free Harbors Compact','alignment':'Allied / independent communities','home':'A treaty among Crownrest, Ossara public wells, Nacre Quay, Aurel Quay and Lumen Tide; no capital','members':['NEW-01','NEW-02','NEW-03','NEW-04','NEW-07'],'purpose':'Protect passage, rescue rights and local ownership of knowledge without turning mutual aid into annexation.','leadership':'Rotating local delegates; any new obligation requires the affected community’s consent.','methods':'Reciprocal refuge, shared weather observations and narrowly scoped archive exchanges.','tension':'Secrecy protects some communities but can endanger visiting travelers. Wealthier ports try to dominate timetables.','ties':'Works with Wayfarers and Commonworks. Opposes water coercion, sky ransom and extraction without agreement.'},
 {'id':'FAC-08','name':'Blackwake Sails','alignment':'Hostile / sky extortion','home':'A mobile fleet using an abandoned mooring outside Aurel Quay','members':['NEW-09'],'purpose':'Turn emergency passage into permanent tribute.','leadership':'Serik commands three small cargo craft; captains bargain over shares and can desert.','methods':'False promises, seized cargo and ransom; real rescue skill makes the deception credible.','tension':'Crew members want profit and survival, not Serik’s theater of heroism.','ties':'Occasional trade with Riven Claw; no global villain command structure. Eri knows their procedures.'},
 {'id':'FAC-09','name':'Still Bell Archive','alignment':'Divided institution / protective and authoritarian wings','home':'Hushvale Echo Archive','members':['NEW-05','NEW-10'],'purpose':'Preserve Severance evidence and assess dangerous resonant crossings.','leadership':'Ossa controls the senior council; Ysolde leads a disclosure faction.','methods':'Technical records, measured closure orders and field inspections. Ossa additionally forged a modern prohibition.','tension':'Real expertise can become a monopoly on judgment. Most archivists are neither villains nor infallible sages.','ties':'Needs independent Hollow Sea records; disputed by Free Harbors; Commonworks can test physical claims.'}]
